class Solution { int single(char c){return c=='*'?9:c=='0'?0:1;}int pairs(char a,char b){if(a=='*')return b=='*'?15:b<='6'?2:1;if(a=='1')return b=='*'?9:1;if(a=='2')return b=='*'?6:b<='6'?1:0;return 0;}public:int numDecodings(string s){const long long mod=1000000007;long long previousTwo=1,previousOne=single(s[0]);for(int i=1;i<(int)s.size();++i){long long current=(single(s[i])*previousOne+pairs(s[i-1],s[i])*previousTwo)%mod;previousTwo=previousOne;previousOne=current;}return previousOne;} };
